style:
width: 100%;
max-width: 520px;
display: flex;
flex-direction: column;
gap: 2rem;
font-size: 0.875rem;
line-height: 1.5rem;
font-weight: 600;
color: var(--navy-900);

children.style:
color: var(--blue-200);
display: inline-flex;
align-items: center;
justify-content: center;
cursor: pointer;
padding: 0 10px ;
border-radius: 4px;
transition: all 200ms ease-in-out;
box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
background-color: var(--navy-600);
border: 1px solid var(--navy-600);
position: relative;
height: 30px;

&:hover {
  border: 1px solid var(--purple-200);
  background-color: var(--slate-500);
}

&:active {
  transform: translateY(1px);
  background-color: var(--accent);
}

position: relative;
font-weight: 600;
color: var(--sky-500);
border-radius: 0.375rem;
cursor: pointer;
background: transparent;
transition: all 0.2s ease;
padding: 0 2px;

&:hover {
  color: var(--sky-300);
}

background: none;
border: none;
color: var(--color-red);
width: 32px;
height: 32px;
cursor: pointer;
line-height: 1;
padding: 0.25rem;
border-radius: 50%;
transition: all 0.2s;

&:hover {
  background: rgba(244, 63, 94, 0.1);
  color: var(--color-red);
}
